const now = new Date();
const madridDate = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Madrid' }).format(now);
const yesterday = new Date(madridDate);
yesterday.setDate(yesterday.getDate() - 1);
const date = yesterday.toISOString().split('T')[0];
const [year, month, day] = date.split('-');

return [{
  json: {
    date, year, month, day,
    prefix: `processed/environment_observations_long/${year}/${month}/${day}/`,
    outputPath: `curated/${year}/${month}/${day}/${year}_${month}_${day}.csv`
  }
}];

// Recibe 24 items (uno por hora) con el contenido CSV de cada fichero
// Los une en un único CSV curated
const allItems = $input.all();
const first = $('Build Download URLs').first().json;
const date = first.date;
const year = first.year;
const month = first.month;
const day = first.day;

let header = '';
const dataRows = [];

for (const item of allItems) {
  // El HTTP Request devuelve el contenido en item.json.data o como texto
  let csvText = '';
  if (typeof item.json === 'string') {
    csvText = item.json;
  } else if (item.json.data) {
    csvText = item.json.data;
  } else {
    // Intentar convertir el objeto a CSV
    csvText = JSON.stringify(item.json);
  }

  const lines = csvText.trim().split('\n');
  if (lines.length < 2) continue;
  if (!header) header = lines[0];
  for (let i = 1; i < lines.length; i++) {
    if (lines[i].trim()) dataRows.push(lines[i]);
  }
}

// Ordena por hora (columna hour, posicion 6)
dataRows.sort(function(a, b) {
  const ha = a.split(',')[6] || '00';
  const hb = b.split(',')[6] || '00';
  return ha.localeCompare(hb);
});

const curatedCsv = header + '\n' + dataRows.join('\n');
const curatedFileName = year + '_' + month + '_' + day + '.csv';
const curatedPath = 'curated/daily_summary/' + year + '/' + month + '/' + day + '/' + curatedFileName;

return [{
  json: { date: date, year: year, month: month, day: day, curatedPath: curatedPath, curatedFileName: curatedFileName, totalRows: dataRows.length },
  binary: {
    data: {
      data: Buffer.from(curatedCsv).toString('base64'),
      mimeType: 'text/csv',
      fileName: curatedFileName
    }
  }
}];
